"""Distinct club values among fixtures."""


def new_clubs(fixtures, seen=set()):
    """Return each club the first time it appears among the fixtures, in order. club values already in `seen` are left out."""
    out = []
    for x in fixtures:
        if x.club not in seen:
            seen.add(x.club)
            out.append(x.club)
    return out


def count_clubs(fixtures):
    """Return how many distinct club values the fixtures have."""
    return len(set(x.club for x in fixtures))


def group_by_club(fixtures):
    """Return a dict from club to the list of fixtures with that club."""
    groups = {}
    for x in fixtures:
        groups.setdefault(x.club, []).append(x)
    return groups
